(function(){ try {
  if (typeof loadAgreementTemplates !== "function" || typeof memStore === "undefined") return;
  var FLAG = "bciq_asset_desc_seed_v1";
  if (memStore.getItem(FLAG)) return;
  var seed = window.BCIQ_AGMT_SEED || [];
  var list = loadAgreementTemplates();
  var have = {}; list.forEach(function(t){ have[String(t.asset||"").trim().toLowerCase()] = 1; });
  var added = 0;
  seed.forEach(function(s){
    var k = String(s.asset||"").trim().toLowerCase();
    if (!k || have[k]) return;
    list.push({ asset: s.asset, section: s.section, headline: s.headline, details: s.details, updatedAt: new Date().toISOString() });
    have[k] = 1; added++;
  });
  if (added && typeof saveAgreementTemplates === "function") saveAgreementTemplates(list);
  memStore.setItem(FLAG, "1");
  if (added) console.log("BlueClaws IQ: seeded " + added + " asset descriptions into the Agreement language library.");
} catch(e){ console.error("asset description seed failed", e); } })();
/* ================= SPONSORSHIP SQUAD SCHEDULE =================
   Who's working each 2026 homestand, how long, and the weekly total against each person's goal.
   Seeded once from Zack's "2026 Sponsorship Schedule" (13 homestands). Rides the same cross-browser
   sync as everything else (channel "squadSchedule", key bciq_squad_schedule). Every cell is editable;
   weekly totals recompute live from the hours entered. 2027 schedule isn't out yet — 2026 only. */
const SQUAD_KEY = "bciq_squad_schedule";
const SQUAD_STATUSES = ["AT GAME", "NOT AT GAME", "NO GAME", "OFF", ""];
function squadClone(x) { return JSON.parse(JSON.stringify(x)); }
function squadSeed() { return Array.isArray(window.BCIQ_SQUAD_SEED) ? squadClone(window.BCIQ_SQUAD_SEED) : []; }
function squadLoad() {
  const d = (typeof nt_load === "function") ? nt_load(SQUAD_KEY) : {};
  if (d && Array.isArray(d.homestands) && d.homestands.length) return d;
  return { v: 1, homestands: squadSeed() };
}
function squadSave(d) { try { nt_save(SQUAD_KEY, "squadSchedule", d); } catch (e) { console.error("squad save failed", e); } }
const squadState = { hs: 0, data: null, autoPicked: false };
function squadNum(x) { const n = parseFloat(String(x == null ? "" : x).replace(/[^0-9.\-]/g, "")); return isNaN(n) ? 0 : n; }
function squadWeekTotal(p) { return (p.days || []).reduce((s, d) => s + squadNum(d.hours), 0); }
// The four department heads get the red treatment; everyone else is an intern (blue).
const SQUAD_HEADS = ["zack", "zak", "cap", "tommy", "joe"];
function squadIsHead(name) { return SQUAD_HEADS.indexOf(String(name || "").trim().toLowerCase()) !== -1; }
/* A "NO GAME" day where the person still logged hours means they were in the office — it should
   NOT read as a red day-off. We surface that as a distinct status flag ("NO GAME IN") so the pill
   styles blue (present) instead of red, without changing the underlying stored status value. */
function squadEffStatus(day) {
  const st = (day && day.status || "").toUpperCase();
  return (/NO GAME/.test(st) && squadNum(day.hours) > 0) ? "NO GAME IN" : st;
}
function squadShortDate(iso) {
  if (!iso) return "";
  const m = String(iso).match(/^(\d{4})-(\d{2})-(\d{2})/);
  return m ? `${Number(m[2])}/${Number(m[3])}` : iso;
}
function squadGoalColor(total, goal) {
  goal = squadNum(goal);
  if (!goal) return "var(--muted)";
  const pct = total / goal;
  if (pct >= 1) return "var(--blue-text)";
  if (pct >= 0.75) return "var(--amber)";   // index257: #b8860b measured 2.86:1 on this paper
  return "var(--red)";
}
function defaultSquadHomestandIndex(hs) {
  const todayIso = isoTodayLocal();
  const normalized = hs.map((h, i) => ({
    i,
    dates: (h.games || []).map(g => g.date).filter(Boolean).sort()
  })).filter(h => h.dates.length);
  const current = normalized.find(h => h.dates[0] <= todayIso && h.dates[h.dates.length - 1] >= todayIso);
  if (current) return current.i;
  const upcoming = normalized.find(h => h.dates[h.dates.length - 1] >= todayIso);
  return upcoming ? upcoming.i : 0;
}
function renderSquadView() {
  const body = document.getElementById("squadBody");
  if (!body) return;
  squadState.data = squadLoad();
  const hs = squadState.data.homestands;
  if (!hs.length) { body.innerHTML = `<div class="table-card" style="padding:var(--space-18);">No homestands loaded.</div>`; return; }
  if (!squadState.autoPicked) { squadState.hs = defaultSquadHomestandIndex(hs); squadState.autoPicked = true; }
  if (squadState.hs >= hs.length) squadState.hs = 0;
  const stand = hs[squadState.hs];
  const games = stand.games || [];
  const people = stand.people || [];
  // homestand switcher
  const opts = hs.map((h, i) => `<option value="${i}"${i === squadState.hs ? " selected" : ""}>${esc((h.title || h.week || ("Homestand " + (i + 1))).replace(/Homestand.*$/i, m => m).slice(0, 80))}</option>`).join("");
  // week KPIs
  const gameCount = games.filter(g => g.firstPitch && !/no game/i.test(g.firstPitch)).length;
  const totalHours = people.reduce((s, p) => s + squadWeekTotal(p), 0);
  const atGameSlots = people.reduce((s, p) => s + (p.days || []).filter(d => /at game/i.test(d.status) && !/not/i.test(d.status)).length, 0);
  const kpi = [
    ["Games this week", gameCount],
    ["Staff hours (wk)", Math.round(totalHours * 10) / 10],
    ["Game shifts covered", atGameSlots],
    ["People", people.length]
  ].map((k, i) => {
    const cols = ["var(--blue)", "var(--gold)", "var(--red)", "var(--navy)"];
    return `<div class="mini-kpi" style="border-top:3px solid ${cols[i % 4]};"><div class="mini-kpi-value">${k[1]}</div><div class="mini-kpi-label">${k[0]}</div></div>`;
  }).join("");
  // header cells for the 7 days
  const dayHead = games.map(g => {
    const bits = [g.theme, g.sponsor ? "Game Sponsor: " + g.sponsor : ""].filter(Boolean);
    const isNo = /no game/i.test(g.firstPitch || "");
    return `<th scope="col" class="squad-dh" style="min-width:132px; text-align:left; padding:var(--space-8); vertical-align:top; border-left:1px solid var(--line);">
        <div style="font-weight:800; font-family:var(--font-display,inherit);">${esc(g.dow || "")} <span style="color:var(--muted); font-weight:600;">${esc(squadShortDate(g.date))}</span></div>
        <div><span class="squad-fp${isNo ? " is-nogame" : ""}">${esc(g.firstPitch || "—")}</span></div>
        ${bits.map(b => `<div style="font-size:10px; color:var(--muted); line-height:1.3; margin-top:2px;">${esc(b)}</div>`).join("")}
      </th>`;
  }).join("");
  // person rows
  const rows = people.map((p, pi) => {
    const total = squadWeekTotal(p);
    const cells = (p.days || []).map((d, di) => {
      const so = SQUAD_STATUSES.map(s => `<option value="${esc(s)}"${(d.status || "") === s ? " selected" : ""}>${esc(s || "—")}</option>`).join("");
      /* index257: this grid is people x days, so a control's meaning comes from two headers at
         once and a screen reader could read neither. Name every field with both. */
      const _who = esc(p.name || "Staff");
      const _day = esc(((games[di] || {}).dow || "") + " " + squadShortDate((games[di] || {}).date));
      return `<td style="padding:var(--space-6); border-left:1px solid var(--line); vertical-align:top;" data-cell="${pi}-${di}">
          <select class="squad-status" aria-label="${_who} — ${_day} status" data-status="${esc(squadEffStatus(d))}" data-p="${pi}" data-d="${di}">${so}</select>
          <div style="display:flex; align-items:center; gap:4px; margin-top:4px;">
            <input class="squad-hours" aria-label="${_who} — ${_day} hours" data-p="${pi}" data-d="${di}" value="${esc(d.hours === 0 || d.hours ? d.hours : "")}" inputmode="decimal" style="width:46px; padding:3px 5px; font-weight:800; font-family:var(--font-display,inherit); border:1px solid var(--line); border-radius:4px; background:var(--card);">
            <span style="font-size:10px; color:var(--muted);">hrs</span>
          </div>
          <div style="display:flex; gap:3px; margin-top:4px;">
            <input class="squad-in" aria-label="${_who} — ${_day} clock in" data-p="${pi}" data-d="${di}" value="${esc(d.in || "")}" placeholder="in" style="width:50%; padding:2px 3px; font-size:9px; border:1px solid var(--line); border-radius:4px; background:var(--card); color:var(--muted);">
            <input class="squad-out" aria-label="${_who} — ${_day} clock out" data-p="${pi}" data-d="${di}" value="${esc(d.out || "")}" placeholder="out" style="width:50%; padding:2px 3px; font-size:9px; border:1px solid var(--line); border-radius:4px; background:var(--card); color:var(--muted);">
          </div>
        </td>`;
    }).join("");
    const goal = squadNum(p.goal);
    const pct = goal ? Math.min(100, Math.round(total / goal * 100)) : 0;
    return `<tr data-prow="${pi}" data-role="${squadIsHead(p.name) ? "head" : "intern"}">
        <th scope="row" class="squad-name" style="text-align:left; padding:var(--space-8) var(--space-10); position:sticky; left:0; background:var(--card); z-index:2; border-right:2px solid var(--line); min-width:120px;">
          <div style="font-weight:800;">${esc(p.name || "")}</div>
          <input class="squad-goal" aria-label="Weekly hour goal for ${esc(p.name || "this person")}" data-p="${pi}" value="${esc(goal || "")}" style="width:44px; padding:2px 4px; font-size:10px; border:1px solid var(--line); border-radius:4px; margin-top:3px; background:var(--card);"> <span style="font-size:9px; color:var(--muted);">goal</span>
          <button type="button" class="squad-del" data-p="${pi}" aria-label="Remove ${esc(p.name || "this person")} from this homestand" title="Remove from this homestand" style="float:right; border:none; background:none; color:var(--red); cursor:pointer; font-size:12px; line-height:1;">✕</button>
        </th>
        ${cells}
        <td style="padding:var(--space-8); border-left:2px solid var(--line); text-align:center; background:var(--paper,transparent);">
          <div class="squad-total" data-p="${pi}" style="font-size:18px; font-weight:800; font-family:var(--font-display,inherit); color:${squadGoalColor(total, goal)};">${Math.round(total * 10) / 10}</div>
          <div style="font-size:9px; color:var(--muted);">of ${goal || "—"}</div>
          <div style="height:4px; border-radius:3px; background:var(--line); margin-top:4px; overflow:hidden;"><div class="squad-bar" data-p="${pi}" style="height:100%; width:${pct}%; background:${squadGoalColor(total, goal)};"></div></div>
        </td>
      </tr>`;
  }).join("");
  // season summary — bar = hours already logged (homestand days on/before today) / each person's
  // full-summer scheduled hours. "% of their summer done", not vs. a goal target.
  const seasonToday = (typeof isoTodayLocal === "function") ? isoTodayLocal() : new Date().toISOString().slice(0, 10);
  const seasonMap = {};
  hs.forEach(h => {
    const gd = (h.games || []).map(g => g.date || "");
    const lastDate = gd.filter(Boolean).sort().slice(-1)[0] || "";
    const standPast = !!lastDate && lastDate <= seasonToday;   // whole homestand already finished
    (h.people || []).forEach(p => {
      const k = (p.name || "").trim(); if (!k) return;
      if (!seasonMap[k]) seasonMap[k] = { name: k, done: 0, total: 0 };
      (p.days || []).forEach((d, di) => {
        const hrs = squadNum(d.hours);
        seasonMap[k].total += hrs;                       // full-summer scheduled hours
        const dt = gd[di] || "";
        const dayDone = dt ? (dt <= seasonToday) : standPast;
        if (dayDone) seasonMap[k].done += hrs;           // hours already logged to date
      });
    });
  });
  /* Overlay the authoritative intern totals imported from the 2026 Sponsorship Schedule.
     The day grid above is incomplete for several interns (it was under-counting by roughly a
     third), so for anyone with a sheet total we trust that number as the real hours logged and
     never let the schedule denominator fall below it. Heads (no intern tab) keep grid math. */
  const AUTH = window.BCIQ_SQUAD_SEASON_HOURS || {};
  Object.keys(AUTH).forEach(nm => {
    if (!seasonMap[nm]) seasonMap[nm] = { name: nm, done: 0, total: 0 };
    seasonMap[nm].done = squadNum(AUTH[nm]);
    seasonMap[nm].total = Math.max(seasonMap[nm].total, squadNum(AUTH[nm]));
    seasonMap[nm].auth = true;
  });
  const seasonRows = Object.values(seasonMap).sort((a, b) => b.done - a.done).map((s, i) => {
    const isHead = squadIsHead(s.name);
    const accent = isHead ? "var(--red)" : "var(--blue)";
    const pct = s.total ? Math.min(100, Math.round(s.done / s.total * 100)) : 0;
    const doneR = Math.round(s.done * 10) / 10, totalR = Math.round(s.total * 10) / 10;
    const tag = s.auth ? ` <span style="font-size:9px; font-weight:700; color:var(--blue-text); background:var(--blue-soft); border:1px solid #bcd9f2; border-radius:var(--radius-pill); padding:1px 6px; margin-left:6px;">from sheet</span>` : "";
    return `<div class="renewal-row" style="grid-template-columns:1fr 120px 150px; align-items:center; border-left:3px solid ${accent}; padding-left:var(--space-10);">
        <strong>${esc(s.name)}${tag}</strong>
        <div title="${pct}% of scheduled hours logged" style="height:6px; border-radius:3px; background:var(--line); overflow:hidden;"><div style="height:100%; width:${pct}%; background:${accent};"></div></div>
        <div style="text-align:right; font-weight:800; font-family:var(--font-display,inherit);">${doneR} <span style="font-size:10px; color:var(--muted); font-weight:600;">/ ${totalR} hrs</span></div>
      </div>`;
  }).join("");

  body.innerHTML = `
    <div class="table-card" style="padding:var(--space-14) var(--space-18); margin-bottom:var(--space-12); display:flex; flex-wrap:wrap; gap:var(--space-10); align-items:center;">
      <button class="secondary-button" id="squadPrev" type="button" style="padding:var(--space-6) var(--space-12);">‹ Prev</button>
      <div class="sfield" style="flex:1 1 300px; margin:0;"><label style="font-size:10px;">Homestand (week)</label><select id="squadHsSelect">${opts}</select></div>
      <button class="secondary-button" id="squadNext" type="button" style="padding:var(--space-6) var(--space-12);">Next ›</button>
      <button class="secondary-button" id="squadAdd" type="button">+ Add staff</button>
      <button class="secondary-button" id="squadReset" type="button">Reset to sheet</button>
    </div>
    <div class="table-card squad-topbar" style="padding:var(--space-14) var(--space-18); margin-bottom:var(--space-12);">
      <div class="eyebrow" style="margin-bottom:var(--space-4);">${esc(stand.title || stand.week || "")}</div>
      <div class="mini-kpis" style="margin-top:var(--space-10);">${kpi}</div>
    </div>
    <div class="table-card squad-tablecard" style="padding:0; margin-bottom:var(--space-14); overflow-x:auto;">
      <table class="squad-table" style="border-collapse:collapse; width:100%; min-width:1080px; font-size:var(--text-xs);">
        <thead><tr>
          <th scope="col" style="text-align:left; padding:var(--space-8) var(--space-10); position:sticky; left:0; background:var(--card); z-index:3; border-right:2px solid var(--line);">Staff</th>
          ${dayHead}
          <th scope="col" style="padding:var(--space-8); border-left:2px solid var(--line); text-align:center;">Week total</th>
        </tr></thead>
        <tbody>${rows}</tbody>
      </table>
    </div>
    <div class="table-card squad-topbar" style="padding:var(--space-14) var(--space-18);">
      <div class="table-toolbar" style="padding:0 0 var(--space-10);"><strong style="font-size:14px;">Season hours by person</strong><span style="margin-left:auto; color:var(--muted); font-size:var(--text-xs);">Hours logged to date vs. each person's full-summer schedule</span></div>
      ${seasonRows || `<div class="readonly-note">No staff yet.</div>`}
    </div>`;

  const recalc = pi => {
    const p = squadState.data.homestands[squadState.hs].people[pi];
    const total = squadWeekTotal(p), goal = squadNum(p.goal);
    const tEl = body.querySelector(`.squad-total[data-p="${pi}"]`);
    const bEl = body.querySelector(`.squad-bar[data-p="${pi}"]`);
    if (tEl) { tEl.textContent = Math.round(total * 10) / 10; tEl.style.color = squadGoalColor(total, goal); }
    if (bEl) { bEl.style.width = (goal ? Math.min(100, Math.round(total / goal * 100)) : 0) + "%"; bEl.style.background = squadGoalColor(total, goal); }
  };
  const cur = () => squadState.data.homestands[squadState.hs];
  document.getElementById("squadHsSelect").addEventListener("change", e => { squadState.hs = +e.target.value; renderSquadView(); });
  document.getElementById("squadPrev").addEventListener("click", () => { squadState.hs = (squadState.hs - 1 + hs.length) % hs.length; renderSquadView(); });
  document.getElementById("squadNext").addEventListener("click", () => { squadState.hs = (squadState.hs + 1) % hs.length; renderSquadView(); });
  body.querySelectorAll(".squad-status").forEach(sel => sel.addEventListener("change", e => {
    const p = +e.target.dataset.p, d = +e.target.dataset.d;
    cur().people[p].days[d].status = e.target.value;
    e.target.dataset.status = squadEffStatus(cur().people[p].days[d]);
    squadSave(squadState.data);
  }));
  body.querySelectorAll(".squad-hours").forEach(inp => {
    inp.addEventListener("input", e => { const p = +e.target.dataset.p, d = +e.target.dataset.d; cur().people[p].days[d].hours = squadNum(e.target.value); recalc(p);
      const sel = body.querySelector(`.squad-status[data-p="${p}"][data-d="${d}"]`); if (sel) sel.dataset.status = squadEffStatus(cur().people[p].days[d]); });
    inp.addEventListener("change", () => window.__squadSaveSoon ? window.__squadSaveSoon(squadState.data) : squadSave(squadState.data));
  });
  /* index213: tabbing across a row used to push the ENTIRE schedule blob to the server four
     times. Saves now coalesce over 600ms and flush if the tab hides. */
  if (!window.__squadSaveSoon) { window.__squadSaveSoon = d => { clearTimeout(window.__sqT); window.__sqT = setTimeout(() => squadSave(d), 600); }; document.addEventListener("visibilitychange", () => { if (document.hidden && window.__sqT) { clearTimeout(window.__sqT); squadSave(squadState.data); } }); }
  body.querySelectorAll(".squad-in").forEach(inp => inp.addEventListener("change", e => { const p = +e.target.dataset.p, d = +e.target.dataset.d; cur().people[p].days[d].in = e.target.value; window.__squadSaveSoon(squadState.data); }));
  body.querySelectorAll(".squad-out").forEach(inp => inp.addEventListener("change", e => { const p = +e.target.dataset.p, d = +e.target.dataset.d; cur().people[p].days[d].out = e.target.value; window.__squadSaveSoon(squadState.data); }));
  body.querySelectorAll(".squad-goal").forEach(inp => { inp.addEventListener("input", e => { const p = +e.target.dataset.p; cur().people[p].goal = squadNum(e.target.value); recalc(p); }); inp.addEventListener("change", () => squadSave(squadState.data)); });
  body.querySelectorAll(".squad-del").forEach(btn => btn.addEventListener("click", async e => {
    const p = +e.currentTarget.dataset.p;
    if (!(await bcConfirm(`Remove ${cur().people[p].name} from this homestand?`, {title:"Remove staff", ok:"Remove", danger:true}))) return;
    cur().people.splice(p, 1); squadSave(squadState.data); renderSquadView();
  }));
  document.getElementById("squadAdd").addEventListener("click", async () => {
    /* index214: staff are picked from the shared people list — two spellings of one intern used
       to mean two rows and two hours goals. The picker still allows adding a new name through
       the sanctioned "+ Add new" path in Requests. */
    pickPersonModal("Add staff to this homestand", async nm => {
      if (!nm || !nm.trim()) return;
      if (cur().people.some(p => (p.name || "").trim().toLowerCase() === nm.trim().toLowerCase())) { toast("Already on this homestand", nm.trim()); return; }
      const g = await bcPrompt("Weekly hours goal for " + nm.trim() + " (number):", "40", {title:"Weekly hours goal", ok:"Save"});
      cur().people.push({ name: nm.trim(), goal: squadNum(g), days: (cur().games || []).map(() => ({ status: "", hours: 0, in: "", out: "" })) });
      squadSave(squadState.data); renderSquadView();
    });
  });
  document.getElementById("squadReset").addEventListener("click", async () => {
    if (!(await bcConfirm("Reset the whole squad schedule back to the original 2026 Sponsorship Schedule? All edits will be lost.", {title:"Reset squad schedule", ok:"Reset", danger:true}))) return;
    squadState.data = { v: 1, homestands: squadSeed() }; squadSave(squadState.data); renderSquadView();
    /* index242 — routine-success toast removed. The action it announced is already visible: the list re-renders, the row updates, or the panel closes. */
  });
}


